class SessionState(Enum):
    """
    SessionState is the lifecycle state of a session.

    The live states are PENDING, LAUNCHING, AWAITING_APPROVAL, RUNNING and
    SUSPENDED. ENDED and INTERRUPTED are terminal. A session in a terminal
    state does not change again.

    ```proto
    enum harnessapi.v1.SessionState
    ```

    Attributes:
        UNSPECIFIED:
            Not set.

            ```proto
            SESSION_STATE_UNSPECIFIED = 0
            ```
        PENDING:
            The server created the session but did not start it.

            ```proto
            SESSION_STATE_PENDING = 1
            ```
        LAUNCHING:
            The server prepares the sandbox and the workspace.

            ```proto
            SESSION_STATE_LAUNCHING = 2
            ```
        AWAITING_APPROVAL:
            The session waits for an approver and for the sandbox to connect.

            ```proto
            SESSION_STATE_AWAITING_APPROVAL = 3
            ```
        RUNNING:
            The agent runs and accepts prompts.

            ```proto
            SESSION_STATE_RUNNING = 4
            ```
        SUSPENDED:
            The agent is stopped. The server keeps the workspace. A Prompt
            revives the session.

            ```proto
            SESSION_STATE_SUSPENDED = 5
            ```
        ENDED:
            The session ended.

            ```proto
            SESSION_STATE_ENDED = 6
            ```
        INTERRUPTED:
            The session ended without a normal stop, for example because the server
            restarted.

            ```proto
            SESSION_STATE_INTERRUPTED = 7
            ```
    """

    UNSPECIFIED = 0
    PENDING = 1
    LAUNCHING = 2
    AWAITING_APPROVAL = 3
    RUNNING = 4
    SUSPENDED = 5
    ENDED = 6
    INTERRUPTED = 7

class Reason(Enum):
    """
    Reason tells why a session changed state.

    ```proto
    enum harnessapi.v1.Reason
    ```

    Attributes:
        UNSPECIFIED:
            No reason applies, for example when the session is created or ends.

            ```proto
            REASON_UNSPECIFIED = 0
            ```
        LAUNCH:
            The first start of the session.

            ```proto
            REASON_LAUNCH = 1
            ```
        REVIVE:
            A Prompt revives a suspended session.

            ```proto
            REASON_REVIVE = 2
            ```
        IDLE:
            The session was idle for too long.

            ```proto
            REASON_IDLE = 3
            ```
        REVIVE_FAILED:
            A revive did not succeed this time, for example because the approval
            lapsed. The session goes back to SESSION_STATE_SUSPENDED. A later revive
            can succeed.

            ```proto
            REASON_REVIVE_FAILED = 4
            ```
        RESUME_UNAVAILABLE:
            A revive found no conversation that the agent can continue, for example
            because the transcript is gone. The session goes back to
            SESSION_STATE_SUSPENDED. Each later revive fails the same way, so end the
            session.

            ```proto
            REASON_RESUME_UNAVAILABLE = 5
            ```
    """

    UNSPECIFIED = 0
    LAUNCH = 1
    REVIVE = 2
    IDLE = 3
    REVIVE_FAILED = 4
    RESUME_UNAVAILABLE = 5

class EndReason(Enum):
    """
    EndReason tells why a session ended.

    ```proto
    enum harnessapi.v1.EndReason
    ```

    Attributes:
        UNSPECIFIED:
            Not set. In EndSession, the server uses END_REASON_ENDED.

            ```proto
            END_REASON_UNSPECIFIED = 0
            ```
        REVOKED:
            Someone revoked the approval.

            ```proto
            END_REASON_REVOKED = 1
            ```
        EXPIRED:
            A time limit ended: the approval, the session lifetime, or the
            retention of a suspended session.

            ```proto
            END_REASON_EXPIRED = 2
            ```
        NEVER_APPROVED:
            The approval offer ended before the session started.

            ```proto
            END_REASON_NEVER_APPROVED = 3
            ```
        AGENT_EXIT:
            The agent process stopped.

            ```proto
            END_REASON_AGENT_EXIT = 4
            ```
        TUNNEL_LOST:
            The server lost its connection to the sandbox.

            ```proto
            END_REASON_TUNNEL_LOST = 5
            ```
        ENDED:
            A client ended the session with EndSession.

            ```proto
            END_REASON_ENDED = 6
            ```
        INTERRUPTED:
            The session stopped without a normal end, for example because the
            server restarted.

            ```proto
            END_REASON_INTERRUPTED = 7
            ```
        PREPARE_FAILED:
            The server could not prepare the workspace.

            ```proto
            END_REASON_PREPARE_FAILED = 8
            ```
        RUN_CREATE_FAILED:
            The server could not ask the authorization server for an approval.

            ```proto
            END_REASON_RUN_CREATE_FAILED = 9
            ```
        ATTACH_TIMEOUT:
            The sandbox did not connect in the permitted time.

            ```proto
            END_REASON_ATTACH_TIMEOUT = 10
            ```
        LAUNCH_FAILED:
            The launch failed for a different reason.

            ```proto
            END_REASON_LAUNCH_FAILED = 11
            ```
        IDLE:
            The session was idle, and the server could not suspend it.

            ```proto
            END_REASON_IDLE = 12
            ```
    """

    UNSPECIFIED = 0
    REVOKED = 1
    EXPIRED = 2
    NEVER_APPROVED = 3
    AGENT_EXIT = 4
    TUNNEL_LOST = 5
    ENDED = 6
    INTERRUPTED = 7
    PREPARE_FAILED = 8
    RUN_CREATE_FAILED = 9
    ATTACH_TIMEOUT = 10
    LAUNCH_FAILED = 11
    IDLE = 12

