class Sentinel(Enum):
    """
    Sentinel is the cause of an error. Each sentinel has one Connect code.
    Use the sentinel, not the code, to decide what to do.

    ```proto
    enum harnessapi.v1.Sentinel
    ```

    Attributes:
        UNSPECIFIED:
            Not set.

            ```proto
            SENTINEL_UNSPECIFIED = 0
            ```
        NOT_FOUND:
            The session or the template does not exist, or it belongs to a
            different client. Code: NotFound.

            ```proto
            SENTINEL_NOT_FOUND = 1
            ```
        UNKNOWN_REQUEST:
            The permission request is not open. Code: NotFound.

            ```proto
            SENTINEL_UNKNOWN_REQUEST = 2
            ```
        FORBIDDEN:
            The client cannot use the API or the template. Code: PermissionDenied.

            ```proto
            SENTINEL_FORBIDDEN = 3
            ```
        CONFLICT:
            A live session with the same conversation_ref exists.
            Code: AlreadyExists.

            ```proto
            SENTINEL_CONFLICT = 4
            ```
        INVALID_STATE:
            The session is not in a state that permits the request.
            Code: FailedPrecondition.

            ```proto
            SENTINEL_INVALID_STATE = 5
            ```
        NOT_REVIVABLE:
            The server cannot revive the suspended session. Start a new session.
            Code: FailedPrecondition.

            ```proto
            SENTINEL_NOT_REVIVABLE = 6
            ```
        INVALID_ARGUMENT:
            A field in the request is not correct. Code: InvalidArgument.

            ```proto
            SENTINEL_INVALID_ARGUMENT = 7
            ```
        UNAVAILABLE:
            The server cannot do the request now. Try again later.
            Code: Unavailable.

            ```proto
            SENTINEL_UNAVAILABLE = 8
            ```
        QUOTA_EXCEEDED:
            The request is above a quota of the client. Code: ResourceExhausted.

            ```proto
            SENTINEL_QUOTA_EXCEEDED = 9
            ```
    """

    UNSPECIFIED = 0
    NOT_FOUND = 1
    UNKNOWN_REQUEST = 2
    FORBIDDEN = 3
    CONFLICT = 4
    INVALID_STATE = 5
    NOT_REVIVABLE = 6
    INVALID_ARGUMENT = 7
    UNAVAILABLE = 8
